// Amino sign-byte parity for every sparkdream Msg, checked against the chain's
// own cosmossdk.io/x/tx/signing/aminojson encoder.
//
// amino-golden.jsonl is generated by the chain repo's cmd/aminogolden: for each
// Msg it holds sample messages as protobuf bytes (seven variants: zero value,
// every field set, lists empty, nested messages present but empty, negative
// integers, non-nullable messages left out, nothing set) and the amino JSON
// the chain renders for them, from the bytes as its tx decoding re-encodes
// them. Regenerate it after
// any proto sync (see .claude/skills/sync-protos/SKILL.md):
//
//   cd <chain> && go run ./cmd/aminogolden golden > <this dir>/amino-golden.jsonl
//
// Each case decodes the bytes with this package's codecs, renders them through
// its AminoConverter maps (the src-overrides where a module has one), and must
// equal the chain's JSON. cosmjs builds the signed tx body from fromAmino, so
// the body encoded from fromAmino's result must render to that JSON too.
import { existsSync, readdirSync, readFileSync } from "fs";
import { join } from "path";
import { Registry } from "@cosmjs/proto-signing";
import { AminoTypes, createDefaultAminoConverters, defaultRegistryTypes } from "@cosmjs/stargate";
import { configureNestedAminoConverter } from "../src/nested-amino";
import { renderAminoJson } from "../src/chain-amino";

// Every module with a Msg service.
const SRC = join(__dirname, "../src/sparkdream");
const MODULES = readdirSync(SRC).filter((m) => existsSync(join(SRC, m, "v1", "tx.registry.ts")));

interface GoldenRecord {
  type_url: string;
  variant: string;
  bytes: string;
  amino: unknown;
}

const registry = new Registry(defaultRegistryTypes);
let converters: Record<string, any> = { ...createDefaultAminoConverters() };
for (const mod of MODULES) {
  require(`../src/sparkdream/${mod}/v1/tx.registry`).load(registry);
  converters = { ...converters, ...require(`../src/sparkdream/${mod}/v1/tx.amino`).AminoConverter };
}
const aminoTypes = new AminoTypes(converters);
configureNestedAminoConverter({ registry: registry as any, aminoTypes: aminoTypes as any });

function sortKeys(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v && typeof v === "object") {
    const o = v as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(o)
        .filter((k) => o[k] !== undefined)
        .sort()
        .map((k) => [k, sortKeys(o[k])]),
    );
  }
  return v;
}
const canon = (v: unknown) => JSON.stringify(sortKeys(v));

// Variants whose bytes omit fields the chain always writes (see chainValues
// in chain-amino.ts).
const SPARSE_VARIANTS = new Set(["absent_non_nullable", "bare"]);

const records: GoldenRecord[] = readFileSync(join(__dirname, "amino-golden.jsonl"), "utf8")
  .split("\n")
  .filter(Boolean)
  .map((l) => JSON.parse(l))
  .filter((r: GoldenRecord) => r.type_url.startsWith("/sparkdream."));

function check(r: GoldenRecord): string | null {
  const codec = registry.lookupType(r.type_url) as any;
  if (!codec) return "not in the registry";
  const bytes = Buffer.from(r.bytes, "hex");
  const want = canon(r.amino);
  let amino: { type: string; value: unknown };
  try {
    if (SPARSE_VARIANTS.has(r.variant)) {
      // These bytes leave non-nullable messages out, as a client's partial
      // value does. Telescope's decode would fill them with its own defaults
      // (the current time for a Timestamp), so render the bytes directly.
      amino = renderAminoJson(r.type_url, bytes) as { type: string; value: unknown };
    } else {
      amino = aminoTypes.toAmino({ typeUrl: r.type_url, value: codec.decode(bytes) });
    }
  } catch (e: any) {
    return `toAmino threw: ${e.message}`;
  }
  if (canon(amino) !== want) return `toAmino\n  got  ${canon(amino)}\n  want ${want}`;
  try {
    // cosmjs signs the JSON, then encodes fromAmino's result as the tx body,
    // and the chain renders that body: it must render to the same JSON.
    const back = aminoTypes.fromAmino(JSON.parse(JSON.stringify(amino)));
    const body = registry.encode({ typeUrl: back.typeUrl, value: back.value });
    const again = renderAminoJson(back.typeUrl, body);
    if (canon(again) !== want) return `fromAmino round trip\n  got  ${canon(again)}\n  want ${want}`;
  } catch (e: any) {
    return `fromAmino threw: ${e.message}`;
  }
  return null;
}

// A Msg added by a proto sync shows up in the registry first; it fails here
// until amino-schema.ts and amino-golden.jsonl are regenerated from the chain.
test("every registered Msg has a converter and golden coverage", () => {
  const registered = MODULES.flatMap((mod) =>
    (require(`../src/sparkdream/${mod}/v1/tx.registry`).registry as [string, unknown][]).map(([url]) => url),
  );
  const covered = new Set(records.map((r) => r.type_url));
  expect(registered.filter((url) => !(url in converters))).toEqual([]);
  expect(registered.filter((url) => !covered.has(url))).toEqual([]);
});

describe("amino JSON matches the chain's aminojson", () => {
  test.each(records.map((r) => [`${r.type_url} [${r.variant}]`, r] as const))("%s", (_label, r) => {
    expect(check(r)).toBeNull();
  });
});
